@startuml

class Company {
  + Name : string
}

class Product {
  + Name : string
  + Description : string
  + NetPrice : double
}

class Country {
  + Name : string
  + VatRate : float
  + Currency : string
  + ConversionRateToEuro : float
}

class Representative {
  + FirstName : string
  + LastName : string
  + SocialSecurityNumber : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Customer {
  + Name : string
  + Address : string
  + TelephoneNumber : string
  + EmailAddress : string
}

class Order {
  + OrderId : string
  + Quantity : int
  + OrderDate : date
  + DesiredDeliveryDate : date
}

Company "1" -- "*" Product
Company "1" -- "*" Country
Product "*" -- "1" Company : manufactured by
Product "*" -- "*" Country : sold in

Representative "1" -- "1" Country : responsible for
Representative "1" -- "*" Order : places
Representative "1" -- "*" Customer : manages

Customer "1" -- "*" Order : places
Customer "*" -- "*" Country : resells in

Order "*" -- "1" Product : refers to

@enduml

